package org.familysearch.mobile.tree.memories

import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.res.stringResource
import org.familysearch.mobile.tree.R

@Composable
fun MemoriesList(memories: List<Memory>, onOpen: (Memory) -> Unit) {
    LazyColumn {
        item { MemoriesGalleryBanner() }
        items(memories, key = { it.id }) { MemoryRow(it, onOpen) }
    }
}

@Composable
fun MemoriesGalleryBanner() {
    Text(stringResource(R.string.memories_gallery_moved), style = MaterialTheme.typography.bodyMedium)
}

package org.familysearch.mobile.tree.memories

import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.res.pluralStringResource
import org.familysearch.mobile.tree.R

@Composable
fun MemoriesList(memories: List<Memory>, sort: MemorySort, onSort: (MemorySort) -> Unit, onOpen: (Memory) -> Unit) {
    LazyColumn {
        item { Text(pluralStringResource(R.plurals.memories_count, memories.size, memories.size)) }
        item { MemoriesSortMenu(sort, onSort) }
        items(memories.sortedWith(sort.comparator), key = { it.id }) { MemoryRow(it, onOpen) }
    }
}

package org.familysearch.mobile.tree.memories

import androidx.compose.material3.DropdownMenuItem
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.res.stringResource
import org.familysearch.mobile.tree.R

enum class MemorySort(val comparator: Comparator<Memory>) {
    NEWEST(compareByDescending { it.created }),
    OLDEST(compareBy { it.created }),
}

@Composable
fun MemoriesSortMenu(sort: MemorySort, onSort: (MemorySort) -> Unit) {
    Text(stringResource(R.string.memories_sort_label))
    DropdownMenuItem(text = { Text(stringResource(R.string.memories_sort_newest)) }, onClick = { onSort(MemorySort.NEWEST) })
    DropdownMenuItem(text = { Text(stringResource(R.string.memories_sort_oldest)) }, onClick = { onSort(MemorySort.OLDEST) })
}
